INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM205F5RU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of 180 moviegoers asked about their favorite genre. Of the 82 moviegoers under age 30, 29 preferred comedy. Of the 98 moviegoers aged 30 or older, 42 preferred comedy. If a moviegoer aged 30 or older is selected at random, what is the probability that this person prefers comedy?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{42}{180}$"},{"key":"B","text":"$\\frac{29}{82}$"},{"key":"C","text":"$\\frac{21}{49}$"},{"key":"D","text":"$\\frac{42}{71}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The question asks for the probability that a randomly selected moviegoer aged 30 or older prefers comedy. This is a conditional probability with the condition being aged 30 or older. There are 98 moviegoers aged 30 or older, and 42 of them prefer comedy, so the probability is 42/98, which simplifies to 21/49. The value 42/180 incorrectly uses the total number of moviegoers as the denominator rather than restricting to the 30-or-older group. The value 29/82 gives the probability for the under-30 group instead. The value 42/71 uses an incorrect denominator of 29 + 42 = 71, summing comedy fans across both age groups rather than counting all moviegoers in the 30-or-older group.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM210GDJ2', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A tank initially contains 190 gallons of water and is being drained at a constant rate. After 7 hours, the tank contains 99 gallons. If the amount of water in the tank is modeled by a linear function \\(W(t)\\), where \\(t\\) is time in hours, what is the rate of change of \\(W(t)\\) in gallons per hour?', NULL, $lyceon_json$[{"key":"A","text":"\\(-13\\)"},{"key":"B","text":"\\(13\\)"},{"key":"C","text":"\\(-91\\)"},{"key":"D","text":"\\(-\\frac{99}{7}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The rate of change is \\(\\frac{99 - 190}{7 - 0} = \\frac{-91}{7} = -13\\) gallons per hour. The negative sign indicates the tank is draining. The distractor 13 drops the negative sign, ignoring that the water level is decreasing. The distractor \\(-91\\) uses the total change in water volume without dividing by the elapsed time. The distractor \\(-\\frac{99}{7}\\) incorrectly uses only the final volume divided by time instead of computing the change from the initial volume.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM211AL4C', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'Store A marks up the wholesale cost of an item by $60\\%$ and then offers a $25\\%$ discount during a sale. Store B marks up the same wholesale cost by $20\\%$ and offers no discount. If the wholesale cost is 140 dollars, how many more dollars does the item cost at Store A than at Store B during Store A''s sale?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$4$"},{"key":"C","text":"$12$"},{"key":"D","text":"$28$"}]$lyceon_json$::jsonb, 'A', NULL, E'Store A: markup price is $140 \\times 1.60 = 224$ dollars. After a $25\\%$ discount: $224 \\times 0.75 = 168$ dollars. Store B: markup price is $140 \\times 1.20 = 168$ dollars. The difference is $168 - 168 = 0$ dollars, so the item costs the same at both stores. The value 4 results from an arithmetic slip in computing the discount. The value 12 comes from incorrectly computing $60\\% - 25\\% = 35\\%$ markup and finding the difference from a $20\\%$ markup. The value 28 comes from only computing the discount amount ($224 - 168 = 56$) and halving it or confusing intermediate steps.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22NGHUI', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $7(3x - 4) - 5x$?', NULL, $lyceon_json$[{"key":"A","text":"$16x - 28$"},{"key":"B","text":"$26x - 28$"},{"key":"C","text":"$16x - 4$"},{"key":"D","text":"$21x - 33$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing the $7$ gives $7 \\cdot 3x - 7 \\cdot 4 = 21x - 28$. Subtracting $5x$ yields $21x - 5x - 28 = 16x - 28$. The distractor $26x - 28$ results from adding $5x$ to $21x$ instead of subtracting it. The distractor $16x - 4$ comes from failing to distribute the $7$ to the $-4$ term, using $-4$ instead of $-28$. The distractor $21x - 33$ comes from subtracting $5$ from the constant $-28$ rather than subtracting $5x$ from the variable term, yielding $21x - 33$ instead of $16x - 28$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM236ZFV1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'grid_in', E'A recipe calls for $\\frac{7}{3}$ cups of broth for every 11 servings. How many cups of broth are needed for 33 servings?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Since 33 servings is 3 times 11 servings, the amount of broth needed is $3 \\times \\frac{7}{3} = 7$ cups. The proportion $\\frac{7/3}{11} = \\frac{x}{33}$ gives $x = \\frac{7 \\times 33}{3 \\times 11} = \\frac{231}{33} = 7$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23BSLIF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A school district wants to determine whether a new reading program improves third-grade test scores. The district randomly assigns 150 third-grade students to either the new program or the traditional program and compares their test scores at the end of the year. This study is best described as', NULL, $lyceon_json$[{"key":"A","text":"a census"},{"key":"B","text":"an observational study"},{"key":"C","text":"a survey"},{"key":"D","text":"an experiment"}]$lyceon_json$::jsonb, 'D', NULL, E'Because the district randomly assigns students to either the new program or the traditional program, treatments are imposed on subjects. This is the defining characteristic of an experiment. A census collects data from every member of a population, which is not what occurred here. An observational study records existing conditions without imposing treatments, but here the programs were assigned by the researcher. A survey collects self-reported data and does not involve assigning treatments.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23CL17A', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A solid is formed by removing a cone from the interior of a cylinder. Both the cone and the cylinder share the same circular base of radius $6$ and the same height of $13$. What is the volume of the resulting solid?', NULL, $lyceon_json$[{"key":"A","text":"$156\\pi$"},{"key":"B","text":"$234\\pi$"},{"key":"C","text":"$312\\pi$"},{"key":"D","text":"$468\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The cylinder volume is $\\pi r^2 h = \\pi(6)^2(13) = 468\\pi$. The cone volume is $\\frac{1}{3}\\pi r^2 h = \\frac{1}{3}(468\\pi) = 156\\pi$. The remaining solid has volume $468\\pi - 156\\pi = 312\\pi$. The value $156\\pi$ is the cone volume alone, which would result from finding only the removed portion rather than the remaining solid. The value $234\\pi$ results from halving the cylinder volume ($468\\pi \\div 2 = 234\\pi$) instead of subtracting one-third. The value $468\\pi$ is the full cylinder volume without subtracting the cone at all.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25OF2BJ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'grid_in', E'In a right triangle, one of the acute angles measures $30°$ and the hypotenuse has length $22$. What is the length of the side opposite the $30°$ angle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'In a $30°$-$60°$-$90°$ triangle, the side opposite the $30°$ angle is half the hypotenuse. Therefore, the side opposite the $30°$ angle has length $\\frac{22}{2} = 11$. Equivalently, using trigonometry: the opposite side equals $22 \\sin(30°) = 22 \\times \\frac{1}{2} = 11$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25ZXFPW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A researcher surveys a random sample of 500 residents from County X and finds that 53% favor a new library, with a margin of error of 4.3 percentage points at 95% confidence. A second researcher surveys a random sample of 500 residents from County Y and finds that 49% favor a new library, with a margin of error of 4.4 percentage points at 95% confidence. Which of the following conclusions is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"The proportion of residents who favor the library is higher in County X than in County Y."},{"key":"B","text":"The proportion who favor the library is exactly 53% in County X and exactly 49% in County Y."},{"key":"C","text":"There is not convincing evidence that the proportions who favor the library differ between the two counties."},{"key":"D","text":"The results cannot be compared because the surveys were conducted in different counties."}]$lyceon_json$::jsonb, 'C', NULL, E'The confidence interval for County X is 53% minus 4.3 to 53% plus 4.3, or 48.7% to 57.3%. The confidence interval for County Y is 49% minus 4.4 to 49% plus 4.4, or 44.6% to 53.4%. These intervals overlap (from 48.7% to 53.4%), meaning the true proportions could be equal. Because the intervals overlap, there is not convincing evidence that the proportions differ. Claiming the proportion is definitively higher in County X ignores the overlap of the intervals and treats the sample statistics as exact values. Stating the proportions are exactly 53% and 49% confuses sample estimates with population parameters. Claiming the results cannot be compared because they come from different counties is incorrect; comparing results from different populations is a standard and valid statistical practice.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26EZ99J', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle has a radius of $9$. A central angle in the circle measures $80°$. What is the area of the sector formed by this central angle?', NULL, $lyceon_json$[{"key":"A","text":"$4\\pi$"},{"key":"B","text":"$18\\pi$"},{"key":"C","text":"$36\\pi$"},{"key":"D","text":"$81\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a sector is $\\frac{\\theta}{360°} \\times \\pi r^2 = \\frac{80}{360} \\times \\pi(9)^2 = \\frac{2}{9} \\times 81\\pi = 18\\pi$. The value $4\\pi$ results from computing the arc length $\\frac{80}{360} \\times 2\\pi(9) = \\frac{2}{9} \\times 18\\pi = 4\\pi$ instead of the sector area. The value $36\\pi$ results from dividing the angle by $180°$ instead of $360°$: $\\frac{80}{180} \\times 81\\pi \\approx 36\\pi$. The value $81\\pi$ is the full circle area $\\pi(9)^2$, omitting the fractional portion defined by the central angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26GEGRE', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'grid_in', E'Two parallel lines are cut by a transversal. One of the co-interior angles (same-side interior angles) formed measures $137°$. What is the measure, in degrees, of the other co-interior angle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '43', ARRAY['43'], E'Co-interior angles (also called same-side interior angles or consecutive interior angles) formed by two parallel lines and a transversal are supplementary, meaning they sum to $180°$. Therefore, the other co-interior angle measures $180° - 137° = 43°$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26LBTLF', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the \\(y\\)-intercept of the line \\(5x + 3y = 21\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\((0, 3)\\)"},{"key":"B","text":"\\((0, 7)\\)"},{"key":"C","text":"\\((0, 21)\\)"},{"key":"D","text":"\\((0, -7)\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'To find the \\(y\\)-intercept, set \\(x = 0\\): \\(3y = 21\\), so \\(y = 7\\). The \\(y\\)-intercept is \\((0, 7)\\). The distractor \\((0, 3)\\) confuses the coefficient of \\(y\\) with the intercept value. The distractor \\((0, 21)\\) uses the constant term directly without dividing by the coefficient. The distractor \\((0, -7)\\) applies an incorrect sign when dividing.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26TS0S1', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has its center at the origin and passes through the point $(0, 11)$. What is the area of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$11\\pi$"},{"key":"B","text":"$22\\pi$"},{"key":"C","text":"$110\\pi$"},{"key":"D","text":"$121\\pi$"}]$lyceon_json$::jsonb, 'D', NULL, E'The radius of the circle is the distance from the center $(0, 0)$ to $(0, 11)$, which is $11$. The area is $\\pi r^2 = \\pi(11)^2 = 121\\pi$. The value $11\\pi$ results from using $\\pi r$ instead of $\\pi r^2$, failing to square the radius. The value $22\\pi$ results from computing the circumference formula $2\\pi r = 2\\pi(11) = 22\\pi$ instead of the area formula. The value $110\\pi$ results from computing $\\pi(11)(10) = 110\\pi$, an arithmetic error in squaring $11$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM271UKZN', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line \\(p\\) has the equation \\(7x - 4y = 20\\). Line \\(q\\) is perpendicular to line \\(p\\) and passes through the point \\((7, -3)\\). What is the \\(y\\)-intercept of line \\(q\\)?', NULL, $lyceon_json$[{"key":"A","text":"1"},{"key":"B","text":"\\(-7\\)"},{"key":"C","text":"\\(\\frac{7}{4}\\)"},{"key":"D","text":"\\(-\\frac{7}{4}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewrite line \\(p\\) in slope-intercept form: \\(y = \\frac{7}{4}x - 5\\), so the slope of \\(p\\) is \\(\\frac{7}{4}\\). The perpendicular slope is \\(-\\frac{4}{7}\\). Using point-slope form with \\((7, -3)\\): \\(y + 3 = -\\frac{4}{7}(x - 7)\\). Simplify: \\(y + 3 = -\\frac{4}{7}x + 4\\), so \\(y = -\\frac{4}{7}x + 1\\). The \\(y\\)-intercept is 1. The distractor \\(-7\\) results from a sign error when distributing the perpendicular slope. The distractor \\(\\frac{7}{4}\\) comes from using the original slope of line \\(p\\) as the intercept without completing the perpendicular calculation. The distractor \\(-\\frac{7}{4}\\) arises from confusing the negative reciprocal relationship with simply negating the original slope and treating it as the intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM283SBOK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A box contains 11 tiles numbered 1 through 11. Two tiles are selected at random without replacement. What is the probability that both tiles show an odd number?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{2}{11}$"},{"key":"B","text":"$\\frac{36}{121}$"},{"key":"C","text":"$\\frac{3}{11}$"},{"key":"D","text":"$\\frac{6}{11}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The odd numbers from 1 through 11 are 1, 3, 5, 7, 9, and 11, giving 6 odd tiles out of 11 total. Since the tiles are drawn without replacement, the probability that the first tile is odd is 6/11, and given that the first tile was odd, the probability that the second tile is also odd is 5/10 = 1/2. Multiplying gives (6/11)(1/2) = 6/22 = 3/11. The value 2/11 results from incorrectly counting only 5 odd numbers and computing (5/11)(4/10) = 20/110 = 2/11. The value 36/121 treats the draws as independent (with replacement), computing (6/11)(6/11). The value 6/11 accounts only for the first draw being odd and ignores the second draw entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28WFKN8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A triangle has a base of $18$ inches and a height of $7$ inches. What is the area, in square inches, of the triangle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '63', ARRAY['63'], E'The area of a triangle is $\\frac{1}{2} \\times \\text{base} \\times \\text{height} = \\frac{1}{2} \\times 18 \\times 7 = \\frac{126}{2} = 63$ square inches.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM290QD2Q', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{25x^2 - 121}{5x + 11}$?', NULL, $lyceon_json$[{"key":"A","text":"$5x + 11$"},{"key":"B","text":"$5x - 11$"},{"key":"C","text":"$5x^2 - 11$"},{"key":"D","text":"$25x - 11$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $25x^2 - 121$ is a difference of squares: $(5x)^2 - 11^2 = (5x - 11)(5x + 11)$. Dividing by $5x + 11$ cancels that factor, leaving $5x - 11$. The distractor $5x + 11$ results from a sign error when factoring the difference of squares, keeping the positive sign instead of the negative. The distractor $5x^2 - 11$ reflects a misunderstanding of polynomial division, dividing only the coefficients ($25 \\div 5 = 5$) while keeping the $x^2$ term. The distractor $25x - 11$ comes from canceling only the constant from the denominator against $121$ but failing to properly simplify $25x^2$ by the full binomial factor.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29FDSPA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'grid_in', E'The ages of 5 members of a committee are 29, 34, 41, 41, and 50. What is the median age?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '41', ARRAY['41'], E'When the values are listed in order (29, 34, 41, 41, 50), the median is the middle value, which is the 3rd value: 41.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29UR6D9', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f(x) = -(x + 6)^2 + 13$ achieves a maximum value. What is that maximum value?', NULL, $lyceon_json$[{"key":"A","text":"$13$"},{"key":"B","text":"$-6$"},{"key":"C","text":"$6$"},{"key":"D","text":"$-13$"}]$lyceon_json$::jsonb, 'A', NULL, E'The function is in vertex form $f(x) = a(x - h)^2 + k$ with $a = -1$, $h = -6$, and $k = 13$. Since $a < 0$, the parabola opens downward and has a maximum value of $k = 13$ at $x = -6$. The distractor $-6$ results from reporting the $x$-coordinate of the vertex rather than the maximum value of the function. The distractor $6$ comes from a sign error on the $x$-coordinate, reading $(x + 6)$ as meaning $h = 6$ instead of $h = -6$. The distractor $-13$ results from negating the maximum value, confusing the negative leading coefficient with the constant term.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29URMY5', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'What value of $x$ satisfies the equation $9x + 17 = 71$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'To solve $9x + 17 = 71$, subtract 17 from both sides to get $9x = 54$, then divide both sides by 9 to get $x = 6$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A764FC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive solution of the equation $x^2 - 2x - 35 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Factor the quadratic: $x^2 - 2x - 35 = (x - 7)(x + 5) = 0$. Setting each factor equal to zero gives $x = 7$ or $x = -5$. The positive solution is $7$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
