INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AUIJYC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $ABC$, $\\angle A = 42°$ and $\\angle B = 71°$. Point $D$ lies on side $BC$ such that $AD$ bisects $\\angle A$. What is the measure, in degrees, of $\\angle ADC$?', NULL, $lyceon_json$[{"key":"A","text":"$88$"},{"key":"B","text":"$92$"},{"key":"C","text":"$109$"},{"key":"D","text":"$113$"}]$lyceon_json$::jsonb, 'B', NULL, E'First, find $\\angle C = 180° - 42° - 71° = 67°$. Since $AD$ bisects $\\angle A$, we have $\\angle DAC = \\frac{42°}{2} = 21°$. In triangle $ADC$, the angle sum gives $\\angle ADC = 180° - 21° - 67° = 92°$. The value $88$ comes from incorrectly using $\\angle B = 71°$ instead of $\\angle C = 67°$ in triangle $ADC$, which actually computes $\\angle ADB$ in the adjacent triangle $ABD$ (since $\\angle ADB + \\angle ADC = 180°$, and $88 + 92 = 180$). The value $109$ results from computing $180° - 71°$, a supplement of $\\angle B$ without proper triangle analysis. The value $113$ results from computing $180° - 67°$, a supplement of $\\angle C$, without accounting for the bisected angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B5LEGP', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line passes through the points \\((2, 11)\\) and \\((5, 23)\\). What is the slope of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'The slope formula gives \\(m = \\frac{23 - 11}{5 - 2} = \\frac{12}{3} = 4\\).', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BKE4LG', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The linear function \\(g\\) is defined such that \\(g(3) = 17\\) and \\(g(11) = 53\\). The function \\(h\\) is defined by \\(h(x) = g(x) - 2x + 9\\). What is the \\(y\\)-intercept of \\(h(x)\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\((0, 12)\\)"},{"key":"B","text":"\\((0, 3.5)\\)"},{"key":"C","text":"\\((0, 12.5)\\)"},{"key":"D","text":"\\((0, 22)\\)"}]$lyceon_json$::jsonb, 'C', NULL, E'First find the slope of \\(g\\): \\(m = \\frac{53 - 17}{11 - 3} = \\frac{36}{8} = \\frac{9}{2}\\). Using point \\((3, 17)\\): \\(g(x) = \\frac{9}{2}(x - 3) + 17 = \\frac{9}{2}x - \\frac{27}{2} + 17 = \\frac{9}{2}x + \\frac{7}{2}\\). Then \\(h(x) = \\frac{9}{2}x + \\frac{7}{2} - 2x + 9 = \\frac{5}{2}x + \\frac{25}{2}\\). Setting \\(x = 0\\): \\(h(0) = \\frac{25}{2} = 12.5\\). The \\(y\\)-intercept is \\((0, 12.5)\\). The distractor \\((0, 12)\\) comes from finding \\(g(x)\\) correctly but forgetting the constant 9 when computing \\(h(x)\\). The distractor \\((0, 3.5)\\) results from an arithmetic slip when combining the constant terms. The distractor \\((0, 22)\\) arises from adding \\(2x\\) instead of subtracting it when constructing \\(h(x)\\).', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FDHBBR', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{x^2 - 11x + 28}{x^2 - 16} \\cdot \\frac{x + 4}{x^2 - 14x + 49}$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{x - 7}$"},{"key":"B","text":"$\\frac{1}{x + 7}$"},{"key":"C","text":"$\\frac{x - 4}{(x + 4)(x - 7)}$"},{"key":"D","text":"$\\frac{1}{(x - 7)^2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor each polynomial: $x^2 - 11x + 28 = (x - 4)(x - 7)$, $x^2 - 16 = (x - 4)(x + 4)$, and $x^2 - 14x + 49 = (x - 7)^2$. The product becomes $\\frac{(x - 4)(x - 7)}{(x - 4)(x + 4)} \\cdot \\frac{x + 4}{(x - 7)^2}$. Canceling the common factors $(x - 4)$, $(x + 4)$, and one $(x - 7)$ leaves $\\frac{1}{x - 7}$. The distractor $\\frac{1}{x + 7}$ arises from a sign error when factoring $x^2 - 11x + 28$ or $x^2 - 14x + 49$, confusing $-7$ with $+7$. The distractor $\\frac{x - 4}{(x + 4)(x - 7)}$ results from only canceling one pair of common factors and stopping before full simplification. The distractor $\\frac{1}{(x - 7)^2}$ reflects failing to cancel one of the $(x - 7)$ factors, misidentifying how many copies cancel between the numerator and denominator.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FTZKE1', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'\\(3x + 2y = 41\\)\\n\\(y = 7\\)\\n\\nWhat is the value of \\(x\\) in the solution to the system of equations above?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Substitute \\(y = 7\\) into the first equation: \\(3x + 2(7) = 41\\), which simplifies to \\(3x + 14 = 41\\). Subtracting 14 from both sides gives \\(3x = 27\\), and dividing both sides by 3 gives \\(x = 9\\).', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G87YLK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'grid_in', E'A jar contains 11 red candies, 5 yellow candies, and 3 orange candies. If one candy is selected at random, what is the probability of selecting a yellow candy?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5/19', ARRAY['5/19', '0.263', '.263'], E'The total number of candies is 11 + 5 + 3 = 19. There are 5 yellow candies, so the probability of selecting a yellow candy is 5/19.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IRLWQK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A researcher recorded the daily coffee consumption and resting heart rates of 320 adults in a city. She found that adults who drank 4 or more cups of coffee per day had higher average resting heart rates than adults who drank no coffee. The researcher concluded that drinking coffee causes an increase in resting heart rate. Which of the following is the best criticism of this conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The sample size of 320 adults is too small to draw any conclusion."},{"key":"B","text":"Because participants were not randomly assigned to coffee consumption groups, the difference could be due to other factors."},{"key":"C","text":"The researcher should have measured heart rate both before and after coffee consumption."},{"key":"D","text":"The conclusion is valid because the sample was large enough to detect a difference."}]$lyceon_json$::jsonb, 'B', NULL, E'This is an observational study because the researcher recorded existing coffee consumption habits rather than assigning participants to drink specific amounts. Without random assignment, confounding variables (such as stress levels, exercise habits, or age) could explain the observed difference in heart rates. Causal conclusions require random assignment to rule out confounders. The claim that 320 adults is too small to draw any conclusion is incorrect; 320 is a reasonable sample size for detecting associations, though sample size does not address the lack of random assignment. Suggesting heart rate should be measured before and after consumption describes a different study design but does not address the fundamental issue that causal claims require random assignment. Asserting the conclusion is valid because the sample is large confuses sample size with study design; a large observational study still cannot establish causation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JYO2ZS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'What is the radius of the circle defined by the equation $$x^2 + y^2 - 14x + 6y + 9 = 0\\,?$$', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$7$"},{"key":"C","text":"$\\sqrt{58}$"},{"key":"D","text":"$49$"}]$lyceon_json$::jsonb, 'B', NULL, E'Completing the square: group and complete each variable. For $x$: $x^2 - 14x + 49 = (x - 7)^2$. For $y$: $y^2 + 6y + 9 = (y + 3)^2$. Adding $49$ and $9$ to both sides of the original equation: $(x - 7)^2 + (y + 3)^2 = -9 + 49 + 9 = 49$. The radius is $\\sqrt{49} = 7$. The value $3$ results from using only the constant $9$ on the right side without properly completing the square, yielding $r = \\sqrt{9} = 3$. The value $\\sqrt{58}$ results from a sign error when moving the constant term: computing $49 + 9 = 58$ without subtracting the original constant, giving $r = \\sqrt{58}$. The value $49$ mistakes $r^2 = 49$ for the radius itself, omitting the square root.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LCM3J2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A company wants to determine whether a new training method increases employee productivity. The company randomly selects 90 employees from its 2,400-person workforce and randomly assigns 47 of them to receive the new training and 43 to receive the standard training. After 6 months, the group receiving the new training has a statistically significantly higher average productivity score. Which of the following conclusions is best supported?', NULL, $lyceon_json$[{"key":"A","text":"There is an association between the training method and productivity, but a causal relationship cannot be established."},{"key":"B","text":"The new training method causes higher productivity among all workers in the industry."},{"key":"C","text":"The new training method causes higher productivity among employees at the company."},{"key":"D","text":"The new training method would increase productivity at any company of similar size."}]$lyceon_json$::jsonb, 'C', NULL, E'This study has two key design features: random selection from the company''s workforce (which allows generalization to all employees at the company) and random assignment to training groups (which allows a causal conclusion). Together, these support the conclusion that the new training method causes higher productivity among employees at the company. The claim that only an association can be established ignores that random assignment was used, which is precisely the mechanism that allows causal inference. The claim about all workers in the industry overgeneralizes beyond the population from which the sample was drawn (the company''s own workforce). Similarly, extending the conclusion to any company of similar size goes beyond the sampled population, since employees were selected only from this particular company.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MELBB8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A chemist mixes Solution A and Solution B in a ratio of $5:3$ by volume. Solution A contains $18\\%$ acid and Solution B contains $42\\%$ acid. What is the acid concentration, in percent, of the resulting mixture?', NULL, $lyceon_json$[{"key":"A","text":"$27$"},{"key":"B","text":"$28.5$"},{"key":"C","text":"$30$"},{"key":"D","text":"$33$"}]$lyceon_json$::jsonb, 'A', NULL, E'In 8 total parts of mixture, 5 parts are Solution A and 3 parts are Solution B. The acid from Solution A is $5 \\times 0.18 = 0.90$ and from Solution B is $3 \\times 0.42 = 1.26$. Total acid is $0.90 + 1.26 = 2.16$ in 8 parts, so the concentration is $\\frac{2.16}{8} = 0.27 = 27\\%$. The value $28.5\\%$ results from using a $4:3$ ratio instead of $5:3$. The value $30\\%$ comes from simply averaging $18\\%$ and $42\\%$ without weighting by volume. The value $33\\%$ arises from an arithmetic error in computing the weighted sum.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MFM8FD', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'A repair service charges a base fee of 47 dollars plus 26 dollars per hour for the first 5 hours. For each additional hour beyond the fifth, the hourly rate increases to 39 dollars. If the total charge for a job is 294 dollars, how many hours did the job take?', NULL, $lyceon_json$[{"key":"A","text":"6"},{"key":"B","text":"7"},{"key":"C","text":"9"},{"key":"D","text":"8"}]$lyceon_json$::jsonb, 'D', NULL, E'The cost for the first 5 hours is $47 + 26(5) = 47 + 130 = 177$ dollars. The remaining charge is $294 - 177 = 117$ dollars, which is billed at 39 dollars per hour: $117 \\div 39 = 3$ additional hours. The total is $5 + 3 = 8$ hours. The value 6 results from computing only one additional hour beyond 5, stopping the calculation prematurely. The value 7 results from incorrectly applying the 26-dollar rate to all hours: $(294 - 47) \\div 26 \\approx 9.5$, then rounding down or miscalculating to get 7. The value 9 results from an arithmetic error when dividing the remaining charge by the overtime rate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MMGF6S', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'grid_in', E'A jacket originally priced at 85 dollars is on sale for 68 dollars. What is the percent discount?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '20', ARRAY['20'], E'The discount amount is $85 - 68 = 17$ dollars. The percent discount is $\\frac{17}{85} \\times 100 = 20\\%$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MPO3U2', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'For the function $f(x) = 7 \\cdot 3^x$, what is the value of $\\frac{f(x + 2)}{f(x)}$ for any value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$3$"},{"key":"C","text":"$6$"},{"key":"D","text":"$21$"}]$lyceon_json$::jsonb, 'A', NULL, E'Compute $f(x + 2) = 7 \\cdot 3^{x+2}$ and $f(x) = 7 \\cdot 3^x$. The ratio is $\\frac{7 \\cdot 3^{x+2}}{7 \\cdot 3^x} = 3^{x+2-x} = 3^2 = 9$. The coefficient $7$ cancels, so the ratio depends only on the base and the shift. The distractor $3$ comes from computing only one step of increase ($3^1$) instead of two, treating the exponent shift as $1$ rather than $2$. The distractor $6$ comes from incorrectly computing $3 \\times 2 = 6$, multiplying the base by the exponent shift instead of raising the base to the power of the shift. The distractor $21$ comes from multiplying the coefficient $7$ by the base $3$, confusing the ratio with $7 \\cdot 3$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N9VY1S', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'\\(7x + 3y = 37\\)\\n\\(2x - 5y = -7\\)\\n\\nWhat is the value of \\(x + y\\) for the solution \\((x, y)\\) to the system of equations above?', NULL, $lyceon_json$[{"key":"A","text":"5"},{"key":"B","text":"7"},{"key":"C","text":"8"},{"key":"D","text":"11"}]$lyceon_json$::jsonb, 'B', NULL, E'Multiply the second equation by 3 to align the \\(y\\)-coefficients: \\(6x - 15y = -21\\). Multiply the first equation by 5: \\(35x + 15y = 185\\). Adding these gives \\(41x = 164\\), so \\(x = 4\\). Substituting back into \\(2(4) - 5y = -7\\) gives \\(8 - 5y = -7\\), so \\(-5y = -15\\) and \\(y = 3\\). Therefore \\(x + y = 4 + 3 = 7\\). Getting 5 results from finding only \\(y = 3\\) and adding incorrectly. Getting 8 results from an arithmetic error during elimination. Getting 11 results from an error in setting up the elimination multipliers.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NM6ZBR', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function \\(f\\) is defined by \\(f(x) = 11x - 37\\). What is the value of \\(f(6)\\)?', NULL, $lyceon_json$[{"key":"A","text":"29"},{"key":"B","text":"103"},{"key":"C","text":"\\(-29\\)"},{"key":"D","text":"\\(37\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Substitute \\(x = 6\\): \\(f(6) = 11(6) - 37 = 66 - 37 = 29\\). The distractor 103 results from adding 37 instead of subtracting. The distractor \\(-29\\) comes from reversing the subtraction order as \\(37 - 66\\). The distractor 37 reflects simply reading the constant from the function without performing the computation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OIRZHF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 400 registered voters in a city finds that 61% support a proposed park renovation, with a margin of error of 4.1 percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly 61% of all registered voters in the city support the park renovation."},{"key":"B","text":"It is plausible that the true percentage of all registered voters in the city who support the park renovation is between 56.9% and 65.1%."},{"key":"C","text":"Between 56.9% and 65.1% of the sampled voters support the park renovation."},{"key":"D","text":"61% of voters in any city would support the park renovation."}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error defines a range around the sample statistic within which the true population parameter plausibly lies. Adding and subtracting 4.1 percentage points from 61% gives the interval 56.9% to 65.1%, so it is plausible that the true percentage of all registered voters who support the renovation falls in this range. The claim that exactly 61% of all voters support it ignores sampling variability entirely. The statement about 56.9% to 65.1% of the sampled voters confuses the population inference with a description of the sample itself; the margin of error applies to the population parameter, not the sample. The claim about voters in any city overgeneralizes beyond the population that was sampled.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OKBMP6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A town''s population increased by $14\\%$ from 2021 to 2022 and then decreased by $7\\%$ from 2022 to 2023. If the population in 2021 was 4,300, what was the population in 2023, rounded to the nearest whole number?', NULL, $lyceon_json$[{"key":"A","text":"$4,559$"},{"key":"B","text":"$4,601$"},{"key":"C","text":"$4,300$"},{"key":"D","text":"$4,731$"}]$lyceon_json$::jsonb, 'A', NULL, E'After a $14\\%$ increase: $4300 \\times 1.14 = 4902$. After a $7\\%$ decrease from the 2022 population: $4902 \\times 0.93 = 4558.86$, which rounds to $4559$. The value $4601$ results from subtracting $7\\%$ of the original 2021 population rather than $7\\%$ of the increased 2022 population: $4902 - (4300 \\times 0.07) = 4902 - 301 = 4601$. The value $4300$ comes from incorrectly assuming the percentage changes cancel out and the population returns to its original value. The value $4731$ comes from only partially applying the decrease, computing $4902 - (4902 - 4300) \\times \\frac{7}{14} \\times \\frac{1}{1} = 4902 - 171 = 4731$, confusing the decrease percentage with a fraction of the increase.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q8XPKK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the number of hours of sunlight per day, $x$, and the daily growth in millimeters of a plant, $y$. The line of best fit is $y = 0.43x - 1.7$. What is the best interpretation of the slope of this line?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour of sunlight, the predicted daily growth increases by $0.43$ millimeters."},{"key":"B","text":"For each additional millimeter of growth, the predicted number of sunlight hours increases by $0.43$."},{"key":"C","text":"A plant receiving zero hours of sunlight is predicted to shrink by $1.7$ millimeters per day."},{"key":"D","text":"For each additional hour of sunlight, the predicted daily growth increases by $1.7$ millimeters."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of $0.43$ represents the change in $y$ (daily growth in mm) for each unit increase in $x$ (hours of sunlight). So for each additional hour of sunlight, the predicted daily growth increases by $0.43$ mm. The option reversing the variables confuses the roles of $x$ and $y$. The option about zero sunlight describes the $y$-intercept, not the slope. The option stating $1.7$ mm increase per hour confuses the slope with the intercept value.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QRTKSM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, angle $P$ measures $47°$ and the exterior angle at vertex $R$ measures $119°$. What is the measure, in degrees, of angle $Q$?', NULL, $lyceon_json$[{"key":"A","text":"$14$"},{"key":"B","text":"$61$"},{"key":"C","text":"$72$"},{"key":"D","text":"$108$"}]$lyceon_json$::jsonb, 'C', NULL, E'By the Exterior Angle Theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles. Thus $119° = 47° + Q$, giving $Q = 72°$. The value $14$ results from finding the interior angle at $R$ ($180° - 119° = 61°$) and then subtracting $47°$, which is an incomplete approach yielding the wrong difference. The value $61$ is the interior angle at $R$ itself, not the requested angle $Q$. The value $108$ comes from taking $180° - 72°$, finding the supplement of the correct answer rather than the answer itself.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RZH473', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'The system of equations $y = x^2 - 5x + 1$ and $y = 2x - 11$ has two solutions. What is the sum of the $y$-coordinates of these two solutions?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-8', ARRAY['-8'], E'Setting the expressions for $y$ equal gives $x^2 - 5x + 1 = 2x - 11$. Rearranging: $x^2 - 7x + 12 = 0$, which factors as $(x - 3)(x - 4) = 0$. So $x = 3$ or $x = 4$. Substituting into $y = 2x - 11$: when $x = 3$, $y = 6 - 11 = -5$; when $x = 4$, $y = 8 - 11 = -3$. The sum of the $y$-coordinates is $-5 + (-3) = -8$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S91APC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'The function $p(x) = ax^2 + bx + c$ has a vertex at $(4, -7)$ and passes through the point $(1, 29)$. What is the value of $c$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '57', ARRAY['57'], E'Using vertex form, $p(x) = a(x - 4)^2 - 7$. Substituting the point $(1, 29)$: $a(1 - 4)^2 - 7 = 29$, so $9a - 7 = 29$, giving $9a = 36$ and $a = 4$. Expanding: $p(x) = 4(x - 4)^2 - 7 = 4(x^2 - 8x + 16) - 7 = 4x^2 - 32x + 64 - 7 = 4x^2 - 32x + 57$. Therefore $c = 57$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TWW2G6', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A bookstore offers free shipping on orders totaling more than 47 dollars. Each book costs 6 dollars, and a flat processing fee of 5 dollars is added to every order. What is the minimum number of books that must be ordered to qualify for free shipping?', NULL, $lyceon_json$[{"key":"A","text":"6"},{"key":"B","text":"7"},{"key":"C","text":"8"},{"key":"D","text":"9"}]$lyceon_json$::jsonb, 'C', NULL, E'The total cost of an order is \\(6b + 5\\), where \\(b\\) is the number of books. Free shipping requires \\(6b + 5 > 47\\). Subtracting 5 from both sides gives \\(6b > 42\\), so \\(b > 7\\). Since the number of books must be a whole number and strictly greater than 7, the minimum is 8. Choosing 7 reflects the error of using \\(\\geq\\) instead of \\(>\\), since \\(6(7) + 5 = 47\\), which does not exceed 47. Choosing 6 reflects omitting the processing fee from the inequality setup. Choosing 9 satisfies the inequality but is not the minimum.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UTCIXN', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'Which of the following points \\((x, y)\\) lies in the solution region of the system of inequalities below?\\n\\n\\(y \\leq -2x + 13\\)\\n\\(y > 3x - 7\\)', NULL, $lyceon_json$[{"key":"A","text":"\\((5, 3)\\)"},{"key":"B","text":"\\((2, 10)\\)"},{"key":"C","text":"\\((1, 2)\\)"},{"key":"D","text":"\\((6, 1)\\)"}]$lyceon_json$::jsonb, 'C', NULL, E'Test each point in both inequalities. For \\((1, 2)\\): first inequality gives \\(2 \\leq -2(1) + 13 = 11\\), which is true; second inequality gives \\(2 > 3(1) - 7 = -4\\), which is true. Both are satisfied, so this point is in the solution region. For \\((5, 3)\\): the first inequality gives \\(3 \\leq -2(5) + 13 = 3\\), which is true, but the second gives \\(3 > 3(5) - 7 = 8\\), which is false. For \\((2, 10)\\): the first inequality gives \\(10 \\leq -2(2) + 13 = 9\\), which is false. For \\((6, 1)\\): the first inequality gives \\(1 \\leq -2(6) + 13 = 1\\), which is true, but the second gives \\(1 > 3(6) - 7 = 11\\), which is false.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UV8NIL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A right circular cylinder has a radius of $7$ and a height of $13$. What is the volume of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$91\\pi$"},{"key":"B","text":"$637\\pi$"},{"key":"C","text":"$182\\pi$"},{"key":"D","text":"$1274\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The volume of a cylinder is $V = \\pi r^2 h$. Substituting $r = 7$ and $h = 13$ gives $V = \\pi(7^2)(13) = \\pi(49)(13) = 637\\pi$. The choice $91\\pi$ results from using $r \\times h = 7 \\times 13 = 91$ without squaring the radius, confusing the formula with circumference or area calculations. The choice $182\\pi$ comes from computing $2\\pi r h = 2\\pi(7)(13) = 182\\pi$, which is the lateral surface area rather than volume. The choice $1274\\pi$ results from doubling the correct answer, likely by mistakenly using $2r^2$ instead of $r^2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V82NUR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set of 8 values has a mean of 47. When a ninth value is added, the mean of the 9 values becomes 51. What is the ninth value?', NULL, $lyceon_json$[{"key":"A","text":"$55$"},{"key":"B","text":"$79$"},{"key":"C","text":"$83$"},{"key":"D","text":"$51$"}]$lyceon_json$::jsonb, 'C', NULL, E'The sum of the original 8 values is $8 \\times 47 = 376$. The sum of all 9 values is $9 \\times 51 = 459$. The ninth value is $459 - 376 = 83$. The value 55 results from incorrectly adding $47 + 8$. The value 79 comes from an error in the subtraction step. The value 51 comes from incorrectly assuming the new value equals the new mean.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VGQ5BA', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'If \\(\\frac{3(2x - 7)}{4} = \\frac{x + 11}{2}\\), what is the value of \\(x\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\frac{43}{4}\\)"},{"key":"B","text":"\\(\\frac{43}{2}\\)"},{"key":"C","text":"\\(\\frac{1}{4}\\)"},{"key":"D","text":"\\(\\frac{1}{2}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Multiply both sides by 4 to clear denominators: \\(3(2x - 7) = 2(x + 11)\\). Expand: \\(6x - 21 = 2x + 22\\). Subtract \\(2x\\) from both sides: \\(4x - 21 = 22\\). Add 21: \\(4x = 43\\). Divide by 4: \\(x = \\frac{43}{4}\\). The distractor \\(\\frac{43}{2}\\) results from forgetting to multiply the right side by 2 when clearing denominators. The distractor \\(\\frac{1}{4}\\) arises from a sign error when combining like terms. The distractor \\(\\frac{1}{2}\\) comes from incorrectly setting up the cross-multiplication.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VW05KF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'For what positive value of $a$ does the equation $$\\frac{7}{x - 3} + \\frac{2}{x + 4} = \\frac{a}{(x - 3)(x + 4)}$$ have no real solution?', NULL, $lyceon_json$[{"key":"A","text":"$22$"},{"key":"B","text":"$27$"},{"key":"C","text":"$49$"},{"key":"D","text":"$63$"}]$lyceon_json$::jsonb, 'C', NULL, E'Multiplying both sides by $(x - 3)(x + 4)$ gives $7(x + 4) + 2(x - 3) = a$, which simplifies to $9x + 22 = a$. This yields $x = \\frac{a - 22}{9}$. The equation has no valid solution when this $x$-value coincides with a restricted value. Since $x \\neq 3$ (denominator restriction), setting $\\frac{a - 22}{9} = 3$ gives $a = 49$. The distractor $22$ comes from only finding the constant term in $9x + 22 = a$ by substituting $x = 0$, an incomplete approach. The distractor $27$ comes from computing $9 \\times 3 = 27$ but forgetting to add $22$. The distractor $63$ comes from incorrectly multiplying $9 \\times 7 = 63$, confusing the coefficient in the numerator with the restricted value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W35FGY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A printer produces 37 pages in 4 minutes. At this rate, how many minutes will it take to print 259 pages?', NULL, $lyceon_json$[{"key":"A","text":"$24$"},{"key":"B","text":"$28$"},{"key":"C","text":"$32$"},{"key":"D","text":"$36$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{37 \\text{ pages}}{4 \\text{ minutes}}$. Setting up the proportion: $\\frac{37}{4} = \\frac{259}{t}$. Solving gives $t = \\frac{259 \\times 4}{37} = \\frac{1036}{37} = 28$ minutes. The value 24 results from a multiplication error when computing $259 \\div 37$. The value 32 comes from incorrectly setting up the proportion and dividing by an incorrect factor. The value 36 arises from confusing the rate relationship and over-multiplying.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W4QMF8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'A $37$-foot wire is attached from the top of a vertical pole to a point on level ground, making a $60°$ angle with the ground. Which of the following gives the height of the pole, in feet?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{37}{2}$"},{"key":"B","text":"$\\frac{37\\sqrt{2}}{2}$"},{"key":"C","text":"$\\frac{37\\sqrt{3}}{2}$"},{"key":"D","text":"$37\\sqrt{3}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The wire is the hypotenuse of a right triangle, and the height of the pole is the side opposite the $60°$ angle. Using $\\sin(60°) = \\frac{\\text{opposite}}{\\text{hypotenuse}}$, the height equals $37 \\sin(60°) = 37 \\times \\frac{\\sqrt{3}}{2} = \\frac{37\\sqrt{3}}{2}$. The value $\\frac{37}{2}$ results from using $\\sin(30°) = \\frac{1}{2}$ instead of $\\sin(60°)$, confusing the two acute angles. The value $\\frac{37\\sqrt{2}}{2}$ results from using $\\sin(45°) = \\frac{\\sqrt{2}}{2}$, applying the wrong special-angle ratio. The value $37\\sqrt{3}$ results from using $\\tan(60°) = \\sqrt{3}$ instead of $\\sin(60°)$, applying tangent when the hypotenuse (not the adjacent side) is known.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WBLC1E', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A scatterplot shows the relationship between the age of a used car, $x$ (in years), and its resale value, $y$ (in thousands of dollars). The equation of the line of best fit is $y = -1.9x + 27.3$, and the actual resale value for a 7-year-old car is 15.1 thousand dollars. What is the residual for this data point, in thousands of dollars?', NULL, $lyceon_json$[{"key":"A","text":"$1.1$"},{"key":"B","text":"$-1.1$"},{"key":"C","text":"$14.0$"},{"key":"D","text":"$-14.0$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted value at $x = 7$ is $y = -1.9(7) + 27.3 = -13.3 + 27.3 = 14.0$. The residual is actual minus predicted: $15.1 - 14.0 = 1.1$ thousand dollars. The value $-1.1$ reverses the residual formula to predicted minus actual. The value $14.0$ gives the predicted value itself rather than the residual. The value $-14.0$ confuses the predicted value with the residual and applies the wrong sign.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WBUN5N', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A line of best fit for a scatterplot is given by $y = 2.3x + 11$. According to the model, what is the predicted value of $y$ when $x = 9$?', NULL, $lyceon_json$[{"key":"A","text":"$31.7$"},{"key":"B","text":"$29.3$"},{"key":"C","text":"$33.0$"},{"key":"D","text":"$20.7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 9$: $y = 2.3(9) + 11 = 20.7 + 11 = 31.7$. The value $29.3$ results from a multiplication error when computing $2.3 \\times 9$. The value $33.0$ comes from misapplying the equation, such as rounding incorrectly. The value $20.7$ comes from computing $2.3 \\times 9$ but forgetting to add the intercept of 11.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WJ0OXY', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'In right triangle $ABC$, the right angle is at $C$. Point $D$ lies on hypotenuse $\\overline{AB}$ such that $\\overline{CD} \\perp \\overline{AB}$. If $AD = 4$ and $DB = 9$, what is the length of $CD$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$6$"},{"key":"C","text":"$6.5$"},{"key":"D","text":"$\\sqrt{13}$"}]$lyceon_json$::jsonb, 'B', NULL, E'When an altitude is drawn from the right-angle vertex to the hypotenuse, the altitude is the geometric mean of the two segments of the hypotenuse. Therefore $CD = \\sqrt{AD \\times DB} = \\sqrt{4 \\times 9} = \\sqrt{36} = 6$. The value $5$ results from a mistaken association with other right-triangle relationships rather than applying the geometric mean altitude theorem. The value $6.5$ results from computing the arithmetic mean $\\frac{4 + 9}{2} = 6.5$ instead of the geometric mean. The value $\\sqrt{13}$ results from computing $\\sqrt{4 + 9}$, adding the segments under the radical instead of multiplying them.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X8LQR6', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'The system of equations below has no solution. What is the value of the constant \\(a\\)?\\n\\n\\((a + 1)x + 8y = 23\\)\\n\\(6x + 12y = 35\\)', NULL, $lyceon_json$[{"key":"A","text":"2"},{"key":"B","text":"3"},{"key":"C","text":"4"},{"key":"D","text":"5"}]$lyceon_json$::jsonb, 'B', NULL, E'A system of two linear equations has no solution when the lines are parallel but not identical — that is, the ratios of the coefficients of \\(x\\) and \\(y\\) are equal, but the ratio of the constants is different. Setting the coefficient ratios equal: \\(\\frac{a+1}{6} = \\frac{8}{12} = \\frac{2}{3}\\). Solving \\(a + 1 = 6 \\cdot \\frac{2}{3} = 4\\) gives \\(a = 3\\). Confirming the lines are not identical: \\(\\frac{23}{35} \\neq \\frac{2}{3}\\), so the system indeed has no solution. Getting 4 results from setting \\(\\frac{a}{6} = \\frac{2}{3}\\) and solving \\(a = 4\\), which omits the \\(+1\\) in the coefficient. Getting 2 results from an arithmetic slip when solving \\(a + 1 = 4\\). Getting 5 results from incorrectly setting \\(\\frac{a+1}{6} = 1\\), misunderstanding the parallel-lines condition.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XR8HN2', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of \\(x\\) satisfies the inequality \\(3x + 11 > 38\\)?', NULL, $lyceon_json$[{"key":"A","text":"7"},{"key":"B","text":"8"},{"key":"C","text":"9"},{"key":"D","text":"11"}]$lyceon_json$::jsonb, 'D', NULL, E'Solving \\(3x + 11 > 38\\): subtract 11 from both sides to get \\(3x > 27\\), then divide both sides by 3 to get \\(x > 9\\). Only 11 is strictly greater than 9. The value 9 is not a solution because the inequality is strict (\\(>\\), not \\(\\geq\\)), so \\(3(9) + 11 = 38\\), which is not greater than 38. The values 7 and 8 both produce results less than 38 when substituted.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZDEF35', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of 350 residents of a town and finds that 43% support a proposed zoning change, with a margin of error of 4.7 percentage points at a 95% confidence level. Which of the following values is a plausible estimate for the true percentage of all town residents who support the zoning change?', NULL, $lyceon_json$[{"key":"A","text":"37.1%"},{"key":"B","text":"39.2%"},{"key":"C","text":"48.9%"},{"key":"D","text":"52.3%"}]$lyceon_json$::jsonb, 'B', NULL, E'The confidence interval is 43% minus 4.7 to 43% plus 4.7, which is 38.3% to 47.7%. A plausible value for the true percentage must fall within this interval. The value 39.2% lies within the interval 38.3% to 47.7%, so it is plausible. The value 37.1% falls below the lower bound of 38.3%. The value 48.9% exceeds the upper bound of 47.7%. The value 52.3% is far outside the interval.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW213PTCW', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'For decades, astronomers assumed that globular clusters — dense spherical collections of ancient stars — formed in a single burst of star formation early in a galaxy''s history. However, spectroscopic analysis of the cluster NGC 2419 revealed two distinct stellar populations with markedly different chemical compositions. This finding prompted researchers to propose that some globular clusters underwent multiple episodes of star formation, with later generations incorporating heavier elements produced by the first.', $lyceon_json$[{"key":"A","text":"It presents a longstanding assumption, introduces evidence that challenges it, and describes the revised understanding that resulted."},{"key":"B","text":"It compares two competing theories about globular clusters and argues that neither is fully supported by the data."},{"key":"C","text":"It describes an experimental method, details the results obtained, and proposes a follow-up study."},{"key":"D","text":"It defines a technical term, provides an example of that term in use, and evaluates the example's significance."}]$lyceon_json$::jsonb, 'A', NULL, E'The text follows a three-part structure: it states the longstanding assumption (single burst of star formation), presents the spectroscopic evidence from NGC 2419 that challenged that assumption (two distinct stellar populations), and then describes the revised understanding (multiple episodes of star formation). The text does not compare two competing theories or argue that neither is supported; it presents one assumption and one revision prompted by evidence. While the text mentions spectroscopic analysis, it does not describe an experimental method in detail or propose any follow-up study. Although the text parenthetically defines "globular clusters," the overall structure is not organized around defining a term and evaluating an example — it is organized around revising an assumption based on new evidence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21I3WVE', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text as a whole?', E'Capybaras, the largest living rodents, are native to South America and are commonly found near bodies of water. Their webbed feet and ability to hold their breath for up to five minutes make them excellent swimmers. _Unlike many rodents, capybaras are highly social animals that live in groups of ten to twenty individuals._ This communal behavior helps them detect predators more effectively and share access to grazing areas.', $lyceon_json$[{"key":"A","text":"It introduces a characteristic that distinguishes capybaras from related animals."},{"key":"B","text":"It provides evidence that capybaras are endangered due to habitat loss."},{"key":"C","text":"It explains why capybaras are classified as rodents."},{"key":"D","text":"It challenges a previous researcher's claim about capybara behavior."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence highlights capybaras'' social nature by explicitly contrasting them with "many rodents," thereby introducing a characteristic that distinguishes them from related animals. The passage never mentions endangerment or habitat loss, so the claim about endangered status is unsupported by the text. The sentence does not explain the basis for capybaras'' taxonomic classification as rodents; it takes that classification as given and notes a behavioral difference. No previous researcher''s claim is mentioned or contested anywhere in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21V9KDO', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice most logically completes the text?', E'Historian Mariana Delgado-Fuentes has argued that the architectural innovations of the Mughal Empire were not merely aesthetic achievements but served strategic military functions. The placement of jharokha balconies, for example, allowed defenders to observe approaching forces from multiple angles while remaining shielded from projectile attacks. _______ Delgado-Fuentes acknowledges that many scholars have interpreted these same features primarily as expressions of imperial grandeur, noting that the elaborate ornamentation on the balconies far exceeded what military utility alone would justify.', $lyceon_json$[{"key":"A","text":"Moreover,"},{"key":"B","text":"In other words,"},{"key":"C","text":"That said,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage first presents Delgado-Fuentes''s argument that Mughal architectural features served military purposes, then shifts to her acknowledgment that many scholars interpret those same features as expressions of grandeur, a concession that partially qualifies her own thesis. The concessive transition ("That said,") correctly signals this shift from advancing a claim to acknowledging a competing interpretation. The additive transition ("Moreover,") incorrectly suggests the final sentence continues to build on the military-function argument rather than qualifying it. The restatement transition ("In other words,") wrongly implies the final sentence rephrases the preceding point rather than introducing a contrasting scholarly perspective. The specification transition ("Specifically,") incorrectly suggests the final sentence provides a narrower detail supporting the military argument, when it actually introduces a counterpoint about aesthetic grandeur.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23BH3SB', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Nutritionist Elara Voss contends that mandatory front-of-package nutrition labels showing sugar content in teaspoons rather than grams would significantly reduce consumer sugar intake. She argues that most shoppers cannot intuitively grasp what 39 grams of sugar means, but easily understand "nearly 10 teaspoons."
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24HEJ5D', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the author of Text 2 most likely characterize the methodology described in Text 1?', E'Text 1: Paleoclimatologist Renata Solís uses oxygen isotope ratios in foraminifera shells extracted from deep-sea sediment cores to reconstruct ocean temperatures over the past 800,000 years. She argues that these proxy records, when calibrated against instrumental data from the past 150 years, provide a reliable continuous temperature signal with a resolution of approximately 500 years per data point.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24ORVJX', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare mineral specimens displayed in the university''s geology department______ visitors from across the region who come specifically to view the formations.', $lyceon_json$[{"key":"A","text":"attract"},{"key":"B","text":"attracts"},{"key":"C","text":"have attracted"},{"key":"D","text":"are attracting"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is "collection," which is singular, not "specimens," which is the object of the prepositional phrase "of rare mineral specimens." The singular verb "attracts" correctly agrees with the singular subject "collection." The plural verb "attract" incorrectly treats the nearer noun "specimens" as the subject. The plural form "have attracted" is wrong because "have" does not agree with the singular "collection." Similarly, "are attracting" uses the plural auxiliary "are," which fails to agree with the singular subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24P53P4', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice most logically completes the text?', E'Entomologist Priya Ramasubramanian has documented that certain species of parasitoid wasps can detect the chemical signatures of caterpillars feeding on tomato plants from distances exceeding fifty meters. Upon locating a host caterpillar, the wasp deposits its eggs inside the caterpillar''s body, where the larvae develop by consuming the host''s tissues. _______ while the wasps'' behavior may appear beneficial to agriculture by reducing pest populations, Ramasubramanian cautions that the wasps are equally attracted to caterpillars feeding on native wildflowers, potentially disrupting pollination networks that depend on those caterpillar species.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"For instance,"},{"key":"C","text":"However,"},{"key":"D","text":"Therefore,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage first describes the wasps'' ability to find and parasitize caterpillars, which implicitly suggests a benefit to agriculture. The sentence after the blank then introduces a complication: the wasps also target caterpillars on native wildflowers, potentially harming pollination networks. This is a contrast between an apparent benefit and an overlooked drawback, so the adversative transition ("However,") correctly signals the shift. The additive transition ("Furthermore,") incorrectly implies the final sentence builds on the preceding point rather than introducing a complication. The exemplification transition ("For instance,") wrongly suggests the final sentence illustrates the parasitic behavior described above rather than qualifying its implications. The causal transition ("Therefore,") incorrectly implies the disruption of pollination networks is a logical conclusion of the preceding description rather than an unexpected complication that cuts against the apparent agricultural benefit.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25Q9IHE', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'If the atmospheric readings collected by the probe during its descent through the clouds of Venus______ consistent with the models that astrobiologists had developed, the scientific community would have had strong grounds for proposing a follow-up mission dedicated to searching for microbial life.', $lyceon_json$[{"key":"A","text":"are"},{"key":"B","text":"were"},{"key":"C","text":"had been"},{"key":"D","text":"would have been"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence describes a past counterfactual condition: the probe''s descent has already occurred, and the readings were not consistent with the models. The result clause uses "would have had," which is the past conditional perfect, requiring the past perfect "had been" in the if-clause to form a correct third conditional. "Had been" correctly indicates that the condition was contrary to fact at a time in the past. The present tense "are" is wrong because it implies the condition might still be true, contradicting the past counterfactual framing. The past subjunctive "were" is used for present unreal conditions (second conditional), not for past counterfactuals; pairing "were" with "would have had" creates an inconsistent mixed conditional that does not match the sentence''s entirely past-oriented timeframe. Placing "would have been" in the if-clause is non-standard; the conditional auxiliary "would" does not belong in a conditional if-clause in Standard English.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26COIK7', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a research summary for a geology course. The student wants to present a finding that challenges a widely held assumption about tectonic activity. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW272UGBH', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second sentence in the overall structure of the text?', E'Literary scholars have long debated whether Zora Neale Hurston''s use of dialect in her 1937 novel constitutes an act of cultural preservation or an inadvertent reinforcement of stereotypes. The debate itself, however, may rest on a false dichotomy: Hurston''s phonetic transcriptions simultaneously document linguistic patterns that were rapidly disappearing and frame those patterns within narrative structures that assert their speakers'' intellectual sophistication. Recent computational analyses of her dialogue have shown that the syntactic complexity of her dialect passages matches or exceeds that of her standard-English narration.', $lyceon_json$[{"key":"A","text":"It introduces a qualification that reframes the scholarly debate described in the first sentence."},{"key":"B","text":"It provides biographical context about the author that explains her motivations."},{"key":"C","text":"It concedes a weakness in the author's literary technique."},{"key":"D","text":"It summarizes the evidence that the third sentence will later present in detail."}]$lyceon_json$::jsonb, 'A', NULL, E'The second sentence begins with "however" and argues that the debate "may rest on a false dichotomy," directly qualifying and reframing the scholarly dispute introduced in the first sentence by suggesting both sides can be true simultaneously. The sentence provides no biographical information about Hurston, such as her background or personal motivations, so the claim about biographical context is unsupported. The sentence does not concede any weakness in Hurston''s technique — it argues that her dialect writing serves dual positive functions. While the third sentence does present computational evidence, the second sentence does not summarize that evidence; instead, it makes the conceptual argument that the dichotomy is false, which is a distinct rhetorical function from summarizing forthcoming data.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28IX5FK', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice can most reasonably be inferred from the text?', E'Economist Renata Boskovic analyzed wage data from 1,247 software firms in Estonia, Latvia, and Lithuania between 2015 and 2023. She found that firms offering fully remote positions paid salaries averaging 14 percent below the prevailing local rate for equivalent in-office roles. However, when Boskovic restricted her analysis to firms that had converted existing in-office positions to remote arrangements — rather than creating new remote-only listings — the wage gap narrowed to 2.3 percent and was not statistically significant. Boskovic noted that firms creating new remote listings were disproportionately drawing applicants from regions with lower costs of living, whereas converted positions retained employees already hired at locally competitive rates.', $lyceon_json$[{"key":"A","text":"Firms in the Baltic states that offered remote work were generally less profitable than firms that required in-office attendance."},{"key":"B","text":"The apparent wage penalty for remote work in the Baltic states was driven largely by geographic sorting of applicants rather than by employers systematically discounting remote positions."},{"key":"C","text":"Employees who transitioned from in-office to remote arrangements experienced a reduction in job satisfaction despite maintaining similar salaries."},{"key":"D","text":"Remote work became less common in the Baltic software industry after 2023 due to employer concerns about productivity."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage shows that the 14 percent wage gap disappears when the analysis is limited to converted positions, and that new remote listings attracted applicants from lower-cost regions. This pattern supports the inference that geographic sorting of the applicant pool — not a deliberate employer discount for remote work — accounts for the observed wage difference. The choice about firm profitability introduces a financial metric the passage never addresses. The choice about reduced job satisfaction raises an outcome the passage does not mention. The choice about remote work declining after 2023 speculates about a trend beyond the study''s timeframe and contradicts nothing stated, but is entirely unsupported by the data presented.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29BP5DE', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly undermine the conclusion drawn by Okoro and Petersen?', E'Political scientists Okoro and Petersen analyzed voter turnout data from 83 municipalities in the Netherlands that adopted online voting portals between 2016 and 2022. They found that average turnout in municipal elections increased by 4.7 percentage points in the two election cycles following portal adoption, compared with a 1.2-point increase in municipalities that retained paper-only balloting. Okoro and Petersen concluded that digital voting infrastructure itself drives higher civic participation, independent of other factors that might simultaneously encourage both portal adoption and turnout growth.', $lyceon_json$[{"key":"A","text":"Several municipalities that adopted online portals reported technical difficulties that temporarily prevented some voters from casting ballots on election day."},{"key":"B","text":"Municipalities that adopted online portals were disproportionately those that had already implemented civic engagement campaigns and simplified voter registration processes in the years before adoption."},{"key":"C","text":"Voter turnout in national elections across the Netherlands remained stable during the same period."},{"key":"D","text":"Online portal adoption required municipalities to invest an average of 340,000 euros in cybersecurity infrastructure."}]$lyceon_json$::jsonb, 'B', NULL, E'Okoro and Petersen concluded that digital infrastructure itself drives turnout, independent of confounding factors. The finding that portal-adopting municipalities had already launched civic engagement campaigns and registration simplification introduces a confound: the turnout increase could be attributable to those pre-existing initiatives rather than the portal, directly undermining the causal claim. The finding about technical difficulties suggests portals occasionally hindered voting but does not address whether the overall turnout increase was caused by the portals or by other factors. The finding about stable national turnout is irrelevant to municipal-level causal claims. The finding about cybersecurity costs addresses implementation expense, not the question of what caused increased participation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CESJCH', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'While studying the migration patterns of Arctic terns across the Norwegian archipelago of Svalbard______ ornithologist Priya Dasgupta recorded flight altitudes that exceeded previous estimates by nearly forty percent.', $lyceon_json$[{"key":"A","text":"Svalbard, ornithologist"},{"key":"B","text":"Svalbard. Ornithologist"},{"key":"C","text":"Svalbard; ornithologist"},{"key":"D","text":"Svalbard: ornithologist"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence begins with a dependent adverbial clause introduced by "While," which must be followed by a comma before the main clause. Using a comma after "Svalbard" correctly separates the introductory dependent clause from the independent clause that follows. A period after "Svalbard" incorrectly fragments the dependent "While" clause, leaving it as an incomplete sentence. A semicolon after "Svalbard" is wrong because semicolons join two independent clauses, and the "While" clause cannot stand alone. A colon after "Svalbard" is incorrect because colons do not separate dependent clauses from main clauses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CND35R', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The murals in the Chauvet Cave, among the oldest known examples of figurative art,______ with such precision that researchers have debated whether the artists possessed an understanding of perspective that predates the Renaissance by over thirty thousand years.', $lyceon_json$[{"key":"A","text":"having been executed"},{"key":"B","text":"was executed"},{"key":"C","text":"were executed"},{"key":"D","text":"executing"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the sentence is "murals," which is plural. The phrase "among the oldest known examples of figurative art" is a parenthetical appositive set off by commas; it does not change the subject. The plural passive verb "were executed" correctly agrees with "murals" and conveys that the murals were created with precision. The participial phrase "having been executed" cannot serve as the main verb of the sentence, leaving the sentence without a predicate. The singular passive "was executed" fails to agree with the plural subject "murals"—students may be misled by the nearer singular noun "art," but the subject remains "murals." The present participle "executing" cannot serve as a finite main verb and also reverses the voice: the murals were executed (created), not doing the executing.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2COZZ44', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice most logically completes the text?', E'The fruit fly Drosophila melanogaster has been a staple organism in genetics laboratories since the early twentieth century. Its rapid reproductive cycle and easily observable mutations make it ideal for studying inheritance patterns. _______ researchers have mapped thousands of genes using Drosophila, contributing significantly to our understanding of chromosomal behavior during cell division.', $lyceon_json$[{"key":"A","text":"Accordingly,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"On the other hand,"},{"key":"D","text":"In contrast,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that Drosophila has qualities making it ideal for genetics research, and the sentence following the blank describes a direct result of those qualities: researchers mapping thousands of genes. The transition indicating a logical consequence ("Accordingly,") correctly captures this cause-and-effect relationship. The option suggesting concession ("Nevertheless,") incorrectly implies the following sentence contradicts the preceding information. The option introducing an alternative perspective ("On the other hand,") wrongly suggests the sentence shifts to a different viewpoint. The option signaling opposition ("In contrast,") falsely implies the mapped genes stand in opposition to the advantages described earlier.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DDUJF4', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Archaeologist Tomoko Hayashi examined ceramic fragments from 14 sites along the Nakdong River basin in southeastern Korea, dating to the period between 300 and 500 CE. She found that vessels recovered from inland hilltop settlements contained clay with a mineral signature consistent with coastal tidal flats located 60 to 90 kilometers away, while coastal site ceramics were uniformly made from local materials. The asymmetry in material sourcing — coastal clay appearing inland but not the reverse — led Hayashi to propose that during this period, ________', $lyceon_json$[{"key":"A","text":"inland communities imported finished ceramic vessels from coastal workshops rather than manufacturing their own pottery."},{"key":"B","text":"coastal communities actively traded raw clay to inland settlements, which then shaped it into vessels locally."},{"key":"C","text":"inland potters deliberately sought coastal clay for its specific material properties, transporting it over considerable distances for local production."},{"key":"D","text":"ceramic technology in the Nakdong basin was more advanced at coastal sites than at inland sites during this period."}]$lyceon_json$::jsonb, 'C', NULL, E'The passage describes ceramic fragments at inland sites made from coastal clay, with the asymmetry suggesting a one-directional material flow. The most logical inference is that inland potters intentionally sourced coastal clay, transporting it for local vessel production — this accounts for both the presence of coastal-origin clay inland and the fact that fragments (not whole vessels) were analyzed. The choice about importing finished vessels is less supported because the passage discusses clay mineral signatures in fragments found at inland sites, which is consistent with local production from imported raw material rather than import of completed goods. The choice about coastal communities trading raw clay attributes the initiative to coastal groups, but the passage''s evidence of asymmetry (inland sites using coastal clay, not the reverse) more directly supports inland demand than coastal supply. The choice about advanced coastal technology is unsupported — the passage describes material sourcing, not relative technological sophistication.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DLOIPY', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what is the most nearly the meaning of "currency"?', E'The ethnomusicologist argued that the pentatonic scale retains remarkable currency across disparate musical traditions. From West African griot songs to Appalachian folk ballads to Japanese gagaku court music, the five-note framework persists not as an archaic relic but as an actively employed compositional resource, suggesting that its appeal transcends any single cultural lineage.', $lyceon_json$[{"key":"A","text":"coinage"},{"key":"B","text":"prevalence"},{"key":"C","text":"value"},{"key":"D","text":"exchange"}]$lyceon_json$::jsonb, 'B', NULL, E'In this passage, "currency" describes the pentatonic scale''s continued widespread use across multiple musical traditions — its prevalence. The passage emphasizes that the scale persists as an "actively employed" resource across diverse cultures, directly supporting the idea of widespread prevalence. "Coinage" refers to the minting of physical money or the invention of a new word, neither of which applies to a musical scale''s cross-cultural persistence. "Value" might seem related since something prevalent could be considered valuable, but the passage is specifically discussing how widespread the scale''s use is, not making a judgment about its worth or importance. "Exchange" refers to a transaction or trade between parties, which is incoherent when describing a musical scale''s persistence across traditions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E0D67V', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Researchers at a university in Reykjavik have found that the volcanic soil of Iceland''s Westfjords region, which is unusually rich in olivine______ accelerates the chemical weathering process that naturally removes carbon dioxide from the atmosphere.', $lyceon_json$[{"key":"A","text":"olivine; accelerates"},{"key":"B","text":"olivine, and accelerates"},{"key":"C","text":"olivine, accelerates"},{"key":"D","text":"olivine. Accelerates"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the clause introduced by "that" is "the volcanic soil," and its main verb is "accelerates." The nonrestrictive relative clause "which is unusually rich in olivine" is an interrupter that must be closed with a comma before the main verb resumes. A comma after "olivine" correctly closes the nonrestrictive clause and allows "accelerates" to function as the main verb. A semicolon after "olivine" would sever the subject from its verb, creating two incomplete fragments within the "that" clause. Adding ", and" after "olivine" would fold "accelerates" into the relative clause as a second verb coordinated with "is," leaving the "that" clause without a main predicate. A period after "olivine" would leave "Accelerates the chemical weathering process" as a fragment without a subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F65ETC', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Ornithologist Priya Narayanan studied the foraging behavior of Clark''s nutcrackers in the Sawtooth Mountains of Idaho. She found that the birds cached an average of 33,000 whitebark pine seeds each autumn, burying them in thousands of individual locations across alpine meadows and south-facing slopes. Remarkably, the nutcrackers retrieved approximately 72 percent of their caches over the following winter and spring. The seeds that the birds failed to retrieve often germinated in locations far from existing stands of whitebark pine. Narayanan therefore suggested that Clark''s nutcrackers serve as ________', $lyceon_json$[{"key":"A","text":"the primary predators of whitebark pine seeds in alpine ecosystems."},{"key":"B","text":"unintentional agents of whitebark pine dispersal and regeneration."},{"key":"C","text":"indicators that whitebark pine populations are declining in Idaho."},{"key":"D","text":"competitors with other bird species for limited food resources at high elevations."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage states that unretrieved seeds germinate far from existing pine stands, leading Narayanan to a conclusion about the birds'' ecological role. The logical completion is that nutcrackers unintentionally disperse and help regenerate whitebark pine. Calling the birds primary predators mischaracterizes their role, since the passage emphasizes seed burial and germination, not consumption. The choice about population decline introduces a claim unsupported by anything in the passage. The choice about competition with other species raises a topic the passage does not address.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FGZ7K9', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice most logically completes the text?', E'During the late Permian period, roughly 252 million years ago, volcanic eruptions in what is now Siberia released vast quantities of carbon dioxide and sulfur compounds into the atmosphere. These emissions triggered severe global warming and ocean acidification over thousands of years. _______ the resulting environmental stress is widely considered the primary driver of the end-Permian mass extinction, which eliminated approximately 81 percent of marine species and 70 percent of terrestrial vertebrate species.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"Regardless,"},{"key":"D","text":"Instead,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes volcanic emissions causing global warming and ocean acidification, and the sentence following the blank identifies the resulting environmental stress as the primary driver of the mass extinction. This is a cause-and-effect chain: eruptions caused atmospheric changes, which in turn caused the extinction event. The transition indicating consequence ("Consequently,") correctly signals this causal progression. The transition suggesting comparison ("Similarly,") incorrectly implies the extinction is being compared to a parallel event rather than presented as a result. The transition meaning "despite that" ("Regardless,") wrongly suggests the extinction occurred in spite of the environmental changes, when in fact it occurred because of them. The transition indicating substitution ("Instead,") falsely implies the extinction replaced or contradicted the environmental stress rather than following from it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IC8RB7', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a proposal for a public health seminar. The student wants to argue that a specific intervention deserves increased funding by connecting its documented outcomes to a broader unmet need. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IZYIDD', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Researchers at the Polytechnic University of Catalonia hypothesized that the unusually high concentration of lithium in certain thermal springs in the Pyrenees Mountains originates not from surface weathering of granitic bedrock, as previously assumed, but from deep-seated hydrothermal fluids rising along fault lines. To test this, the team analyzed the isotopic ratios of lithium-6 to lithium-7 in water samples from 19 thermal springs and compared them with ratios found in local granite, regional rainwater, and deep crustal fluids sampled from boreholes in analogous geological settings.', $lyceon_json$[{"key":"A","text":"The lithium isotopic ratios in the thermal spring water closely matched those of deep crustal fluids rather than those of the local granite."},{"key":"B","text":"The temperature of the thermal springs was found to vary seasonally by as much as 11 degrees Celsius."},{"key":"C","text":"Granite samples collected near the springs contained lithium concentrations 17 percent higher than the regional average."},{"key":"D","text":"Rainwater in the Pyrenees region was found to contain trace amounts of lithium consistent with atmospheric deposition from Saharan dust events."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers'' hypothesis is that lithium in the springs comes from deep hydrothermal fluids, not from surface weathering of granite. A finding that the spring water''s isotopic ratios match deep crustal fluids rather than granite would directly corroborate this source. The finding about seasonal temperature variation describes a physical property of the springs unrelated to the lithium source. The finding about high lithium concentrations in nearby granite would, if anything, lend plausibility to the alternative surface-weathering explanation, working against the hypothesis. The finding about Saharan dust in rainwater addresses an entirely different lithium pathway that is not part of the hypothesis under test.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KW6XZB', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The soil samples collected by the rover Perseverance from Jezero Crater on Mars, samples that planetary scientists believe may contain biosignatures of ancient microbial life______ are scheduled to be returned to Earth by a joint NASA-ESA retrieval mission no earlier than 2033.', $lyceon_json$[{"key":"A","text":"life; are"},{"key":"B","text":"life, and are"},{"key":"C","text":"life, are"},{"key":"D","text":"life. Are"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the sentence is "The soil samples," and its main verb is "are scheduled." The phrase "samples that planetary scientists believe may contain biosignatures of ancient microbial life" is an appositive renaming "soil samples" and must be closed with a comma before the main verb continues. A comma after "life" correctly closes the appositive and allows the main verb "are scheduled" to follow. A semicolon after "life" would separate the subject from its verb, splitting the sentence into two incomplete parts. Adding ", and are" after "life" is incorrect because "and" would need a parallel main-clause verb to coordinate with, but no prior main-clause verb exists. A period after "life" would leave "Are scheduled to be returned" as a fragment with no subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L4YRXG', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Neuroscientist Yael Bhatt has challenged the prevailing view that mirror neurons — cells that fire both when an organism performs an action and when it observes the same action performed by another — are the primary neural substrate for empathy. Bhatt acknowledges that mirror neuron activity correlates with action understanding, but she argues that empathy requires an additional cognitive layer: the capacity to distinguish one''s own emotional state from that of another person. In a 2023 study of 241 participants, Bhatt found that individuals with high mirror neuron responsiveness but impaired self-other distinction, as measured by a novel autobiographical interference task, scored no higher on validated empathy assessments than control participants. Bhatt concludes that mirror neurons are necessary but insufficient for empathic response.', $lyceon_json$[{"key":"A","text":"Mirror neurons have been definitively shown to play no role in generating empathic responses in humans."},{"key":"B","text":"Bhatt's research demonstrates that empathy depends on self-other distinction rather than on any neural mirroring activity."},{"key":"C","text":"A neuroscientist argues that empathy requires not only mirror neuron activity but also the ability to differentiate between one's own emotions and those of others."},{"key":"D","text":"Bhatt's study of 241 participants was the first to measure mirror neuron responsiveness using an autobiographical interference task."}]$lyceon_json$::jsonb, 'C', NULL, E'The passage presents Bhatt''s argument that mirror neurons alone are insufficient for empathy; a second cognitive capacity — self-other distinction — is also required. The correct choice captures both components of this claim. The choice stating mirror neurons play no role contradicts Bhatt''s conclusion that they are necessary. The choice framing empathy as depending on self-other distinction rather than mirroring omits Bhatt''s explicit position that mirror neurons remain necessary, capturing only half the argument. The choice about the autobiographical interference task being the first of its kind introduces a claim the passage never makes — the task is described as novel, but the passage does not say it was the first to measure mirror neuron responsiveness.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MKTXA1', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'A student claims that the spotted lanternfly poses a significant economic threat to agriculture. Which finding, if true, would most directly support this claim?', E'The spotted lanternfly (Lycorma delicatula), an invasive planthopper native to parts of China and Vietnam, was first detected in the United States in Berks County, Pennsylvania, in 2014. The insect feeds on the sap of over 70 plant species, including grapevines, fruit trees, and hardwoods. When feeding, it excretes a sugary substance called honeydew, which promotes the growth of sooty mold on leaves and fruit. State agricultural agencies across the mid-Atlantic region have established quarantine zones and encouraged residents to destroy egg masses found on outdoor surfaces.', $lyceon_json$[{"key":"A","text":"Spotted lanternflies were likely transported to Pennsylvania on a shipment of landscaping stone from eastern Asia."},{"key":"B","text":"Vineyards in southeastern Pennsylvania reported crop losses of 43 percent in areas with heavy lanternfly infestations between 2018 and 2021."},{"key":"C","text":"The spotted lanternfly's natural predators in its native range include parasitoid wasps of the genus Anastatus."},{"key":"D","text":"Entomologists have observed that spotted lanternflies tend to aggregate in groups of 30 to 50 individuals on tree trunks during late summer."}]$lyceon_json$::jsonb, 'B', NULL, E'The claim concerns economic threat to agriculture. The finding about vineyard crop losses of 43 percent directly quantifies agricultural damage caused by the lanternfly, which supports the claim. The finding about how the insect arrived in Pennsylvania addresses its origin, not its economic impact. The finding about parasitoid wasps concerns biological control in the native range, which does not demonstrate economic harm. The finding about aggregation behavior describes a habit that does not, by itself, establish agricultural damage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PY94Z4', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what is the most nearly the meaning of "tempered"?', E'The architect''s enthusiasm for the avant-garde glass facade was tempered by her awareness of the building''s location in a seismically active zone. She ultimately proposed a hybrid design that preserved the visual transparency she favored while incorporating reinforced steel mullions at every seventh panel.', $lyceon_json$[{"key":"A","text":"heated"},{"key":"B","text":"provoked"},{"key":"C","text":"moderated"},{"key":"D","text":"forged"}]$lyceon_json$::jsonb, 'C', NULL, E'Here "tempered" means that the architect''s enthusiasm was moderated — restrained or kept in check — by practical safety concerns, leading to a compromise design. "Heated" suggests increasing temperature or intensity, which contradicts the passage''s indication that enthusiasm was being checked rather than amplified. "Provoked" means deliberately incited or angered, which mischaracterizes the relationship between enthusiasm and safety awareness described. "Forged" refers to shaping metal through hammering or fabricating something, neither of which fits the context of how awareness influenced the architect''s feelings.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SIUTZA', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief introduction about the baobab tree for a nature magazine aimed at general readers. The student wants to emphasize the tree''s unusual physical characteristics. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2V7BAQP', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what is the most nearly the meaning of "modest"?', E'A team of marine biologists studying coral reefs in the Andaman Sea reported that the reef system had shown only modest recovery after a severe bleaching event three years prior. While some sections displayed new polyp growth, the overall extent of regeneration fell well below projections.', $lyceon_json$[{"key":"A","text":"humble"},{"key":"B","text":"limited"},{"key":"C","text":"bashful"},{"key":"D","text":"affordable"}]$lyceon_json$::jsonb, 'B', NULL, E'In this passage, "modest" describes a recovery that "fell well below projections," indicating the recovery was limited in scope or extent. The word "humble" refers to a person''s demeanor or social standing, which is incoherent when describing a reef''s recovery. "Bashful" means shy or timid, a personality trait that cannot logically apply to coral regeneration. "Affordable" refers to cost, which has no relevance to the biological recovery described in the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XHNGO4', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the linguist Renata Vogel completed her analysis of the newly discovered manuscript in 2021, she______ over three hundred previously unrecorded loanwords from medieval Occitan that had entered the regional dialect of Catalonia.', $lyceon_json$[{"key":"A","text":"identifies"},{"key":"B","text":"has identified"},{"key":"C","text":"had identified"},{"key":"D","text":"would identify"}]$lyceon_json$::jsonb, 'C', NULL, E'The construction "By the time [subject] completed" establishes that one past action was finished before another past action. This requires the past perfect tense in the main clause to indicate the earlier of the two past events. "Had identified" correctly signals that the identification of loanwords was completed before the analysis was finished. The present tense "identifies" is wrong because the entire sentence is set in the past. The present perfect "has identified" is incorrect because present perfect connects past actions to the present, but the sentence describes a relationship between two past events. The conditional "would identify" implies a hypothetical or future-in-the-past scenario, which does not fit the factual framing of the sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XZA3ZU', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'In 2019, marine biologists at the University of Bergen discovered that Arctic cod populations in the Barents Sea had shifted their spawning grounds approximately 137 kilometers northward over the previous two decades. The researchers attributed this migration to rising sea temperatures, which had increased by an average of 1.3 degrees Celsius in the region since 1998. As the cod followed cooler waters, fishing communities along Norway''s northern coast found themselves adjusting their operations to pursue the relocated stocks, sometimes traveling significantly farther from port than in previous years.', $lyceon_json$[{"key":"A","text":"Rising sea temperatures in the Barents Sea have caused Arctic cod to relocate their spawning grounds northward, affecting nearby fishing communities."},{"key":"B","text":"Norwegian fishing communities have modernized their fleets to travel greater distances from port."},{"key":"C","text":"The University of Bergen has become a leading institution in Arctic marine research."},{"key":"D","text":"Arctic cod populations are declining because of temperature increases in the Barents Sea."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how Arctic cod shifted spawning grounds northward due to rising temperatures and how fishing communities adjusted in response. The correct choice captures both elements: the temperature-driven relocation and its impact on fishing communities. The choice about fleet modernization focuses on a detail not stated in the text — the passage says communities traveled farther, not that they modernized. The choice about the university''s research prominence is unsupported by anything in the passage. The choice about population decline misreads the passage: the cod relocated, but the text does not state their numbers decreased.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YFDHNP', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes a difference in how the authors of Text 1 and Text 2 approach the topic of urban green spaces?', E'Text 1: Urban planner Miriam Ortega argues that cities should prioritize converting vacant lots into community gardens and pocket parks. She cites a 2021 study of 47 mid-sized American cities showing that neighborhoods with green spaces within a 400-meter walking radius experienced a 23 percent decrease in reported stress-related health complaints.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YSUH7A', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'Historian Camille Robichaud has argued that the 1847 typhus epidemic aboard immigrant ships bound for Quebec was not merely a public health catastrophe but a pivotal moment in Canadian immigration policy. Prior to the epidemic, which killed an estimated 5,293 passengers during transit, colonial authorities had exercised minimal oversight of shipping conditions. Robichaud contends that the scale of death aboard vessels like the Syria and the Virginius compelled lawmakers to impose the Passenger Acts of 1848, which mandated minimum space allotments per passenger, required ships to carry a qualified surgeon, and established quarantine protocols at Grosse Île. These legislative responses, Robichaud maintains, represented the first systematic attempt by Canadian authorities to regulate the conditions under which immigrants arrived.', $lyceon_json$[{"key":"A","text":"The 1847 typhus epidemic was the deadliest maritime disaster in Canadian history."},{"key":"B","text":"A historian argues that the 1847 typhus epidemic prompted transformative changes in Canadian immigration regulation."},{"key":"C","text":"Colonial authorities were negligent in their treatment of immigrants before and after the 1847 epidemic."},{"key":"D","text":"The Passenger Acts of 1848 failed to prevent future outbreaks of disease on immigrant ships."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage presents Robichaud''s argument that the 1847 typhus epidemic served as a catalyst for systematic immigration regulation in Canada, culminating in the Passenger Acts of 1848. The correct choice accurately captures this central claim. The choice calling it the deadliest maritime disaster makes a superlative claim the passage never supports. The choice about ongoing negligence after the epidemic contradicts the passage, which describes legislative reforms that followed. The choice about the Passenger Acts failing addresses an outcome the passage does not discuss.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YZLMX5', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the Kepler space telescope was originally designed to survey a single patch of sky for Earth-sized exoplanets______ mission engineers later repurposed the spacecraft to observe different regions of the Milky Way after a mechanical failure in 2013 limited its pointing capability.', $lyceon_json$[{"key":"A","text":"exoplanets; mission"},{"key":"B","text":"exoplanets, mission"},{"key":"C","text":"exoplanets. Mission"},{"key":"D","text":"exoplanets, and mission"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence opens with a dependent clause introduced by "Although," which requires a comma to separate it from the independent clause that follows. A comma after "exoplanets" correctly marks the boundary between the subordinate "Although" clause and the main clause beginning with "mission engineers." A semicolon after "exoplanets" is incorrect because a semicolon joins two independent clauses, and the "Although" clause is dependent. A period after "exoplanets" is wrong for the same reason: it would leave the "Although" clause as a sentence fragment. Adding ", and" after "exoplanets" is incorrect because "and" requires two parallel independent clauses to coordinate, but the "Although" clause is subordinate, making the conjunction structurally invalid.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
